import exp from 'express'
import { connect } from 'mongoose'
import { config } from 'dotenv'
import { userApp } from './APIS/UserApis.js'
import cors from 'cors'

config()
const app = exp()
const port = Number(process.env.PORT) || 3000
const databaseUrl = process.env.MONGODB_URI || 'mongodb://127.0.0.1:27017/stack01'
const allowedOrigins = new Set([
  process.env.CLIENT_URL || 'http://localhost:5173',
  'http://127.0.0.1:5173'
])

app.use(cors({
  origin(origin, callback) {
    if (!origin || allowedOrigins.has(origin)) {
      callback(null, true)
      return
    }

    callback(new Error('Origin not allowed by CORS'))
  }
}))
app.use(exp.json())

app.get('/health', (req, res) => {
  res.status(200).json({
    message: 'Server is healthy'
  })
})

app.use('/user-api', userApp)

async function connectDb() {
  try {
    const db = await connect(databaseUrl)
    console.log('Connected to database')

    // Clean up old unique indexes if they exist to allow partial indexes
    try {
      const collection = db.connection.collection('users')
      const indexes = await collection.indexes()
      const indexNames = indexes.map(idx => idx.name)
      if (indexNames.includes('email_1')) {
        await collection.dropIndex('email_1')
        console.log('Dropped old email_1 index')
      }
      if (indexNames.includes('mobilenumber_1')) {
        await collection.dropIndex('mobilenumber_1')
        console.log('Dropped old mobilenumber_1 index')
      }
    } catch (indexErr) {
      console.log('Error dropping old indexes:', indexErr)
    }

    if (!process.env.VERCEL) {
      app.listen(port, () => {
        console.log(`Server started listening at port ${port}`)
      })
    }
  } catch (err) {
    console.log('Error in connecting to DB', err)
  }
}

connectDb()


app.use((req, res) => {
  res.status(404).json({
    message: `Invalid path ${req.url}`
  })
})

app.use((err, req, res, next) => {
  if (err.name === "ValidationError") {
    return res.status(400).json({
      message: "Validation failed",
      errors: err.errors,
    })
  }

  if (err.name === "CastError") {
    return res.status(400).json({
      message: "Invalid ID format",
    })
  }

  if (err.code === 11000) {
    const duplicateField = Object.keys(err.keyPattern || {})[0] || "field"

    return res.status(409).json({
      message: `${duplicateField} already exists`,
    })
  }

  const statusCode = err.statusCode || 500
  const message = statusCode >= 500
    ? "Internal Server Error"
    : err.message

  if (statusCode >= 500) {
    console.error(err)
  }

  res.status(statusCode).json({
    message,
  })
})

export default app

